// TripServiceHandler is an implementation of the loci.trip.TripService service.
type TripServiceHandler interface {
	SaveTrip(context.Context, *connect.Request[trip.SaveTripRequest]) (*connect.Response[trip.TripDraft], error)
	GetTrip(context.Context, *connect.Request[trip.GetTripRequest]) (*connect.Response[trip.TripDraft], error)
	ListTrips(context.Context, *connect.Request[trip.ListTripsRequest]) (*connect.Response[trip.ListTripsResponse], error)
	// ShareTrip is the old sharing call: is_public = true sets LINK visibility,
	// false sets PRIVATE. Use SetTripVisibility.
	//
	// Deprecated: do not use.
	ShareTrip(context.Context, *connect.Request[trip.ShareTripRequest]) (*connect.Response[trip.ShareTripResponse], error)
	// SetTripVisibility sets who may open the trip and returns its share link
	// (minted on first use; empty for PRIVATE).
	SetTripVisibility(context.Context, *connect.Request[trip.SetTripVisibilityRequest]) (*connect.Response[trip.SetTripVisibilityResponse], error)
	// GetSharedTrip opens a trip by its share code. Accepts anonymous callers.
	// PRIVATE trips, and trips whose owner blocked the caller, are NotFound.
	// Stop notes and booking links are left out unless the owner opted in.
	GetSharedTrip(context.Context, *connect.Request[trip.GetSharedTripRequest]) (*connect.Response[trip.TripDraft], error)
	// GetFriendTrip opens another user's trip by id when the caller may see it
	// (FRIENDS for a friend, or PUBLIC); otherwise NotFound.
	GetFriendTrip(context.Context, *connect.Request[trip.GetFriendTripRequest]) (*connect.Response[trip.TripDraft], error)
	// ListFriendTrips is the caller's feed: trips friends shared as FRIENDS or
	// PUBLIC, most recently updated first.
	ListFriendTrips(context.Context, *connect.Request[trip.ListFriendTripsRequest]) (*connect.Response[trip.ListTripsResponse], error)
	// ListUserTrips lists the trips of one user that the caller may see.
	ListUserTrips(context.Context, *connect.Request[trip.ListUserTripsRequest]) (*connect.Response[trip.ListTripsResponse], error)
	// CopyTrip saves a trip the caller may see as a new trip of their own,
	// private, with copied_from_trip_id set. Later changes to the source do
	// not touch the copy.
	CopyTrip(context.Context, *connect.Request[trip.CopyTripRequest]) (*connect.Response[trip.CopyTripResponse], error)
	ReorderStops(context.Context, *connect.Request[trip.ReorderStopsRequest]) (*connect.Response[trip.TripDraft], error)
	RenameStop(context.Context, *connect.Request[trip.RenameStopRequest]) (*connect.Response[trip.TripDraft], error)
	EditStopDuration(context.Context, *connect.Request[trip.EditStopDurationRequest]) (*connect.Response[trip.TripDraft], error)
	SetConstraint(context.Context, *connect.Request[trip.SetConstraintRequest]) (*connect.Response[trip.TripDraft], error)
	AddStop(context.Context, *connect.Request[trip.AddStopRequest]) (*connect.Response[trip.TripDraft], error)
	RemoveStop(context.Context, *connect.Request[trip.RemoveStopRequest]) (*connect.Response[trip.TripDraft], error)
	ReplaceStop(context.Context, *connect.Request[trip.ReplaceStopRequest]) (*connect.Response[trip.TripDraft], error)
	// The trip's plan. Each takes base_version and answers FailedPrecondition
	// when it is stale, like the stop edits above.
	SetTripDates(context.Context, *connect.Request[trip.SetTripDatesRequest]) (*connect.Response[trip.TripDraft], error)
	SetStay(context.Context, *connect.Request[trip.SetStayRequest]) (*connect.Response[trip.TripDraft], error)
	ClearStay(context.Context, *connect.Request[trip.ClearStayRequest]) (*connect.Response[trip.TripDraft], error)
	AddFlight(context.Context, *connect.Request[trip.AddFlightRequest]) (*connect.Response[trip.TripDraft], error)
	RemoveFlight(context.Context, *connect.Request[trip.RemoveFlightRequest]) (*connect.Response[trip.TripDraft], error)
	BuildFlightLinks(context.Context, *connect.Request[trip.BuildFlightLinksRequest]) (*connect.Response[trip.BuildFlightLinksResponse], error)
	ExportTrip(context.Context, *connect.Request[trip.ExportTripRequest]) (*connect.Response[trip.ExportTripResponse], error)
	// SuggestPacking derives a packing list from the trip: its length, its cities'
	// forecasts, the driving between them, and the traveller's stated interests.
	SuggestPacking(context.Context, *connect.Request[trip.SuggestPackingRequest]) (*connect.Response[trip.SuggestPackingResponse], error)
	// GetTripChecklist returns the trip's packing items, expenses and dismissed
	// packing suggestions. Other users' trips are NotFound.
	GetTripChecklist(context.Context, *connect.Request[trip.GetTripChecklistRequest]) (*connect.Response[trip.GetTripChecklistResponse], error)
	// UpsertChecklistItem creates or replaces an item by (trip_id, item.id).
	// Adding a 501st item is ResourceExhausted.
	UpsertChecklistItem(context.Context, *connect.Request[trip.UpsertChecklistItemRequest]) (*connect.Response[trip.ChecklistItem], error)
	// DeleteChecklistItem removes an item; deleting a missing item succeeds.
	DeleteChecklistItem(context.Context, *connect.Request[trip.DeleteChecklistItemRequest]) (*connect.Response[trip.DeleteChecklistItemResponse], error)
	// DismissPackingSuggestion hides a suggestion from this trip's checklist.
	DismissPackingSuggestion(context.Context, *connect.Request[trip.DismissPackingSuggestionRequest]) (*connect.Response[trip.DismissPackingSuggestionResponse], error)
}

